struct Livro {
    titulo: String,
    conteudo: String,
}

fn ler_livro(livro: Livro) {
    println!("Lendo o livro: {}", livro.titulo);
}

fn main() {
    let livro_de_calculo = Livro {
        titulo: "Cálculo I".to_string(),
        conteudo: "Limites, Derivadas...".to_string(),
    };

    // O primeiro estudante lê o livro
    ler_livro(livro_de_calculo);

    // O segundo estudante tenta ler o mesmo livro
    println!("Minha vez de ler: {}", livro_de_calculo.titulo);
}
